+// Regression: Ollama emits the parsed tool call of some models (e.g. qwen3-coder) only in
+// the final done=true frame. The stream handler must still surface it.
+func TestOllamaStreamHandlerToolCallsInDoneFrame(t *testing.T) {
+	gin.SetMode(gin.TestMode)
