    rejectUnauthorized: false,
    key: read('bad.key'),
    cert: read('bad.crt'),
    minVersion: tlsVersion,
    maxVersion: tlsVersion,
  });

  socket.on('secureConnect', () => {
    events.push('secureConnect');
    socket.write('GET / HTTP/1.1\r\nHost: localhost\r\n\r\n', error => {
      events.push(error ? `write:${error.code}` : 'write');
    });
  });
  socket.on('error', error => events.push(`error:${error.code}:${error.message}`));
  socket.on('end', () => events.push('end'));
  socket.on('close', hadError => {
    events.push(`close:${hadError}`);
    console.log(`${process.versions.bun ? `bun ${process.versions.bun}` : `node ${process.version}`}: ${events.join(' -> ')}`);
  });
  socket.setTimeout(4000, () => socket.destroy(new Error('timeout')));
} else {
  const clientRuntime = process.argv[2];
  if (!clientRuntime)
    throw new Error('usage: node repro.mjs <node-or-bun-executable>');

  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bun-mtls-eof-'));
  const openssl = (...args) => execFileSync('openssl', args, { cwd: dir, stdio: 'ignore' });
  const read = name => fs.readFileSync(path.join(dir, name));

  openssl('req', '-x509', '-newkey', 'rsa:2048',
    '-keyout', 'server.key', '-out', 'server.crt', '-days', '2', '-nodes', '-subj', '/CN=localhost');
  openssl('req', '-x509', '-newkey', 'rsa:2048',
    '-keyout', 'bad.key', '-out', 'bad.crt', '-days', '2', '-nodes', '-subj', '/CN=untrusted-client');

  const server = tls.createServer({
    key: read('server.key'),
    cert: read('server.crt'),
    ca: read('server.crt'),
    requestCert: true,
    rejectUnauthorized: true,
    minVersion: tlsVersion,
    maxVersion: tlsVersion,
  });
  server.on('tlsClientError', () => {});
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));

  const child = spawn(clientRuntime, [script, 'client', String(server.address().port), dir], {
    stdio: 'inherit',
  });
  const exitCode = await new Promise((resolve, reject) => {
    child.once('error', reject);
    child.once('close', resolve);
  });
  await new Promise(resolve => server.close(resolve));
  fs.rmSync(dir, { recursive: true, force: true });
  process.exitCode = exitCode;
}
```

Run the parent/server with Node.js in both cases and switch only the child/client runtime:

```console
$ node repro.mjs node
node v22.23.2: secureConnect -> write -> end -> close:false

$ node repro.mjs bun
bun 1.4.0: secureConnect -> write -> error:ECONNRESET:read ECONNRESET -> close:true
```

I also reproduced the Node result with Node v26.8.1 and the Bun result with `1.4.1-canary.1+731aa92da`. The TLS 1.3 result was stable in 20/20 runs.

As a control, pinning the same script to TLS 1.2 makes Node and Bun agree:

```console
$ TLS_VERSION=TLSv1.2 node repro.mjs node
node v22.23.2: end -> error:ECONNRESET:Client network socket disconnected before secure TLS connection was established -> close:true

$ TLS_VERSION=TLSv1.2 node repro.mjs bun
bun 1.4.0: end -> error:ECONNRESET:Client network socket disconnected before secure TLS connection was established -> close:true
```

### What is the expected behavior?

Match Node.js for the established TLS 1.3 socket: emit `end`, followed by `close` with `hadError === false`, without emitting `ECONNRESET`.

```text
secureConnect -> write -> end -> close:false
```

### What do you see instead?

Bun turns the post-handshake EOF into a socket error:

```text
secureConnect -> write -> error:ECONNRESET:read ECONNRESET -> close:true
```

### Additional information

This appears to be an unexpected EOF / bare FIN without `close_notify`, rather than a TLS fatal alert:

- This is not #40380 / #40384. That case receives `close_notify + FIN` and concerns a pending backpressured write failing with `ERR_SOCKET_CLOSED`. The small write in this reproduction completes before EOF.
- This is not #33294. That PR handles a post-handshake fatal TLS alert such as `certificate_required`. The Node baseline here emits no TLS alert error; it emits a clean `end`.
- #33630 explains the relevant server-side behavior: when Node rejects a presented client certificate, its destroy path closes without `SSL_shutdown`, leaving the peer to observe an unexpected EOF rather than `close_notify`.
- #40412 is closely related at the transport level but covers the opposite direction: making Bun send a Node-compatible bare FIN when destroying a TLS socket. This report concerns how Bun receives that EOF on an established TLS 1.3 client socket.

Downstream impact: Playwright implements browser client certificates through a TLS proxy using `node:tls`. With the same rejected self-signed client certificate, the Node.js driver produces Chromium's `net::ERR_EMPTY_RESPONSE`, while the Bun driver produces `net::ERR_SOCKET_NOT_CONNECTED`. This breaks the client-certificate integration test when running the Playwright driver with Bun: https://github.com/YusukeIwaki/playwright-ruby-client/pull/393

Shell injection: JSON.stringify used as shell quoting in four execSync call sites

`JSON.stringify()` escapes `"` and `\`. It does not escape `$( )`, backticks, or `${}`, all of which still expand inside double quotes under `/bin/sh`. Four sites use it (or something weaker) as if it were shell quoting.

```console
$ sh -c 'echo "harmless: $(echo PWNED-COMMAND-RAN)"'
harmless: PWNED-COMMAND-RAN
```

Reviewed at v3.5.0.

### 1. `skill/scripts/lib/is-generated.mjs:44` — reached from a full project tree walk

```js
execSync(`git check-ignore --quiet ${JSON.stringify(absPath)}`, {
  cwd,
  stdio: 'ignore',
});
```

This is the one that matters, because `absPath` is not a path the user typed. `live-wrap.mjs:733` passes every file the source search walks:

```js
fileFilter: (filePath) => genOpts.includeGenerated || !isGeneratedFile(filePath, genOpts),
```

So a repository that contains a file or directory whose name embeds `$(...)` or backticks executes that command as soon as the walk reaches it — cloning a project and running a live-mode command is enough. `live-accept.mjs:242`, `live-insert.mjs:169`, `live-commit-manual-edits.mjs:233`/`:623` and `live-manual-edit-evidence.mjs:172`/`:259` reach the same function with paths from session state.

Fix is a one-liner — the argv form never involves a shell:

```js
execFileSync('git', ['check-ignore', '--quiet', absPath], { cwd, stdio: 'ignore' });
```

### 2. `skill/scripts/live.mjs:317` — no escaping at all

```js
function runScript(name, args, options = {}) {
  const scriptPath = path.join(__dirname, name);
  const cmd = `node "${scriptPath}" ${args.map(a => `"${a}"`).join(' ')}`;
  return execSync(cmd, { encoding: 'utf-8', ... });
```

Raw interpolation into double quotes, so a single `"` in an arg ends the quoting outright. Current callers (`:124`, `:144`, `:348`) pass literals, so this is latent rather than live — but it is the shape that invites a future caller to pass a path or a user string. `execFileSync(process.execPath, [scriptPath, ...args])` removes the class.

### 3. `cli/bin/commands/skills.mjs:1366` and `:1371` — baked into a persistent hook command

```js
quotedPath = JSON.stringify(hookScript);
...
return guardHookCommand(quotedPath);
```

```js
function guardHookCommand(quotedPath) {
  return `[ ! -f ${quotedPath} ] || node ${quotedPath}`;
}
```

`hookScript` comes from `hookScriptPathForProvider(skillRoot, provider)` — the install root, i.e. the project directory or `$HOME`. The result is written into `settings.local.json` and executed by the harness on **every** `Edit`/`Write` and on `Stop`. A directory name containing `$(...)` anywhere in the install path turns into repeat execution rather than a one-shot.

Since the string has to stay POSIX-shell, this one needs real single-quote escaping rather than `JSON.stringify`:

```js
const shQuote = (s) => `'${String(s).replace(/'/g, `'\\''`)}'`;
```

### 4. `skill/scripts/hook-lib.mjs:1112` — suggested command shown to the agent

```js
function quoteCommandArg(value) {
  const text = String(value || '').trim();
  if (/^[A-Za-z0-9._:-]+$/.test(text)) return text;
  return `"${text.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}
```

Feeds `formatFindingIgnoreCommand` (`:1100`), which builds an `impeccable hooks ignore-value ...` command from a value extracted out of the scanned file (`extractFindingIgnoreValueRaw:868` pulls font-family names and Google Fonts params straight from file content). That command string goes into the model's context as a suggestion. Lowest severity of the four — the finding line gates it on *"If the user explicitly confirms this value is intentional"* — but a `font-family: "$(...)"` in a scanned CSS file still ends up as a shell command a human is being nudged to approve. Same single-quote fix.

---

Happy to send a PR for all four if that is useful.

